#include <cmath>
#include <algorithm>
extern "C" void render(const double* pts,int n,float* out,int res,double side){
 double px=side/res,rx=pts[0],ry=pts[1],theta=atan2(pts[4]-ry,pts[3]-rx),w=0,d=0;
 for(int k=0;k<n;k++){
  double x=pts[3*k],y=pts[3*k+1],z=std::min(15.,pts[3*k+2]);
  double W=z>0?std::max(0.,1.187*z-.3):0,D=z>0?1.075*z+1.38:0,O=z>0?std::max(0.,-.0967*z*z+2.109994*z-.36001727):0;
  w=.02*w+.98*W;d=.02*d+.98*D;
  double vx=x-rx,vy=y-ry,L=hypot(vx,vy),o=std::min(O,L);
  if(L>(z>0?1.:.1))theta=atan2(vy,vx);
  if(L>0){rx=x-vx*o/L;ry=y-vy*o/L;}
  if(z<=0||w<.001)continue;
  double ex=cos(theta),ey=sin(theta),nx=-ey,ny=ex,hw=w/2;
  double xs[4]={rx+hw*nx,rx-hw*nx,rx-d*ex+hw*nx,rx-d*ex-hw*nx};
  double ys[4]={ry+hw*ny,ry-hw*ny,ry-d*ey+hw*ny,ry-d*ey-hw*ny};
  int c0=std::max(0,(int)floor(*std::min_element(xs,xs+4)/px-1.5));
  int c1=std::min(res-1,(int)ceil(*std::max_element(xs,xs+4)/px+.5));
  int r0=std::max(0,(int)floor(*std::min_element(ys,ys+4)/px-1.5));
  int r1=std::min(res-1,(int)ceil(*std::max_element(ys,ys+4)/px+.5));
  for(int r=r0;r<=r1;r++)for(int c=c0;c<=c1;c++){
   double qx=(c+.5)*px-rx,qy=(r+.5)*px-ry;
   double s=-(qx*ex+qy*ey),t=qx*nx+qy*ny;
   double f=d*(1-4*t*t/(w*w))-s,g=sqrt(1+pow(8*d*t/(w*w),2));
   float a=std::max(0.,std::min(1.,std::min(s,f/g)/px+.5));
   out[r*res+c]=std::max(out[r*res+c],a);
  }
 }
}
