import numpy as np, cv2, ctypes, time,json
from scipy.interpolate import PchipInterpolator, CubicSpline
from scipy.optimize import minimize
from scipy.ndimage import distance_transform_edt, binary_erosion
from pathlib import Path
OUT=Path('/app/output'); SIDE=227.18450651397864; SCALE=SIDE/1024
lib=ctypes.CDLL(str(OUT/'brush_render.so'))
lib.render.argtypes=[np.ctypeslib.ndpointer(dtype=np.float64,flags='C_CONTIGUOUS'),ctypes.c_int,np.ctypeslib.ndpointer(dtype=np.float32,flags='C_CONTIGUOUS'),ctypes.c_int,ctypes.c_double]
initial=[
 [[416,310,0],[471,336,8],[519,379,14],[515,449,14],[510,522,13],[507,588,12],[510,637,11],[506,651,0]],
 [[288,502,0],[312,558,7],[308,609,11],[283,663,12],[303,683,9],[376,676,10],[469,647,10],[560,620,9],[630,604,8],[675,623,4],[677,622,0]],
 [[651,445,0],[692,472,10],[707,515,12],[718,564,14],[737,610,14],[720,629,9],[675,605,8],[614,587,6],[566,558,0]]
]
def samples(nodes,step=.2):
 # Time proportional to 3D path length, with minimum duration for pressure transitions.
 nodes=np.asarray(nodes); t=np.r_[0,np.cumsum(np.maximum(np.linalg.norm(np.diff(nodes,axis=0),axis=1),.5))]
 ts=np.linspace(0,t[-1],int(np.ceil(t[-1]/step))+1)
 xy=PchipInterpolator(t,nodes[:,:2],axis=0)(ts)
 z=PchipInterpolator(t,nodes[:,2])(ts)
 return np.ascontiguousarray(np.c_[xy,z])
def draw(paths,res=512,step=.2):
 out=np.zeros((res,res),np.float32)
 for nodes in paths:
  p=samples(nodes,step);lib.render(p,len(p),out,res,SIDE)
 return out

def metrics(im,targ):
 a=im>=.5;b=targ>.5;inter=(a&b).sum();union=(a|b).sum();px=SIDE/len(a)
 da=distance_transform_edt(~a)*px;db=distance_transform_edt(~b)*px
 ea=a^binary_erosion(a);eb=b^binary_erosion(b)
 p=(distance_transform_edt(~eb)[ea]*px<=1).mean();r=(distance_transform_edt(~ea)[eb]*px<=1).mean()
 return dict(iou=inter/union,recall=inter/b.sum(),precision=inter/a.sum(),stray=((db>1)&a).sum()/b.sum(),bf=2*p*r/(p+r))
def save(paths,name='fit'):
 np.savez(OUT/f'{name}.npz',**{f'p{i}':p for i,p in enumerate(paths)})
 im=draw(paths,1024,.12);targ=cv2.imread('/app/target.png')[:,:,0]<100
 rgb=np.ones((1024,1024,3),np.uint8)*245
 rgb[targ]=[180,150,150];rgb[im>=.5]=[50,50,50];rgb[targ&(im>=.5)]=[10,10,10]
 cv2.imwrite(str(OUT/f'{name}.png'),rgb)
 print(name,metrics(im,targ),flush=True)
if __name__=='__main__':
 import argparse
 ap=argparse.ArgumentParser();ap.add_argument('--load');ap.add_argument('--rounds',type=int,default=3);args=ap.parse_args()
 if args.load:
  a=np.load(args.load);paths=[a[k] for k in a.files]
 else:
  paths=[np.array(p,float)*[SCALE,SCALE,1] for p in initial]
 save(paths,'initial')
 res=384;target=cv2.resize((cv2.imread('/app/target.png')[:,:,0]<100).astype(np.float32),(res,res),interpolation=cv2.INTER_AREA)
 # Extra cost for ink outside tolerance.
 dist=distance_transform_edt(target<.5)*SIDE/res
 weight=1+2*np.minimum(dist/2,3)
 shape=[p.shape for p in paths];sizes=[p.size for p in paths];splits=np.cumsum(sizes)[:-1]
 def unpack(x):return [p.reshape(s) for p,s in zip(np.split(x,splits),shape)]
 x=np.concatenate([p.ravel() for p in paths]);base=x.copy()
 bounds=[]
 for p in paths:
  for i,(xx,yy,z) in enumerate(p):
   bounds.extend([(xx-9,xx+9),(yy-9,yy+9),(0,0) if i in (0,len(p)-1) else (.5,16)])
 count=0;best=1e9;start=time.time()
 def objective(x):
  global count,best
  ps=unpack(x);im=draw(ps,res,.3)
  # missing versus extraneous area, emphasizing distant stray ink.
  loss=np.sum(np.maximum(target-im,0)+weight*np.maximum(im-target,0))/target.sum()
  # Preserve writing motion, penalize excess deviation very gently.
  loss+=.00002*np.sum(((x-base)/np.tile([1,1,2],sum(len(p) for p in ps)))**2)
  count+=1
  if loss<best:
   best=loss
  if count%500==0:print('eval',count,'loss',loss,'best',best,'sec',time.time()-start,flush=True)
  return loss
 for rnd in range(args.rounds):
  result=minimize(objective,x,method='Powell',bounds=bounds,options={'maxiter':8,'xtol':.025,'ftol':.0002})
  x=result.x;paths=unpack(x);save(paths,f'fit{rnd}');save(paths,'fit')
